use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (result: Vec<i32>)
    requires
        1 <= k < list.len(),
    ensures
        result.len() == list.len() - 1,
        forall|i: int| 0 <= i < k - 1 ==> result[i] == list[i],
        forall|i: int| k - 1 <= i < result.len() ==> result[i] == list[i + 1],
{
    let n = list.len();
    let mut new_list = Vec::with_capacity(n - 1);

    new_list.extend_from_slice(&list[0..k-1]);
    
    assert(new_list.len() == k - 1);
    assert(forall|i: int| 0 <= i < new_list.len() ==> new_list[i] == list[i]);

    new_list.extend_from_slice(&list[k..n]);
    
    assert(new_list.len() == (k - 1) + (n - k));
    assert(new_list.len() == n - 1);
    assert(forall|i: int| 0 <= i < k - 1 ==> new_list[i] == list[i]);
    assert(forall|i: int| k - 1 <= i < new_list.len() ==> new_list[i] == list[i + 1]);

    new_list
}

}

